function normalize(str) {
  return String(str || '')
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/đ/g, 'd')
    .replace(/Đ/g, 'D')
    .trim();
}

function getTelegramContext(source) {
  const payload = source.payload || {};
  const message = source.message || payload.message || payload.body?.message || {};
  const chatId = source.chatId || message.chat?.id || payload.chatId || '';
  const rawText = String(source.rawText || source.text || message.text || message.caption || payload.text || '').trim();
  return { payload, message, chatId, rawText };
}

function cleanName(value) {
  return String(value || '')
    .trim()
    .replace(/^[\"'“”‘’]+|[\"'“”‘’]+$/g, '')
    .replace(/\s+/g, ' ');
}

const source = $('Execute Workflow Trigger').item.json || {};
const ctx = getTelegramContext(source);
const raw = ctx.rawText;
const normalized = normalize(raw);
const prefixes = ['them vao doc', 'append doc', 'ghi them vao tai lieu'];
let body = raw;
for (const prefix of prefixes) {
  if (normalized.startsWith(prefix + ' ')) {
    body = raw.slice(prefix.length + 1).trim();
    break;
  }
}

let docId = source.docId || source.fileId || source.targetId || '';
let docName = cleanName(source.docName || source.fileName || '');
let content = String(source.content || '').trim();

if ((!docName || !content) && body) {
  const separator = body.indexOf(':');
  if (separator !== -1) {
    docName = docName || cleanName(body.slice(0, separator));
    content = content || body.slice(separator + 1).trim();
  } else {
    const markerMatch = body.match(/\s+(?:noi dung|nội dung|content)\s*[:=-]?\s*/i);
    if (markerMatch) {
      const idx = markerMatch.index || 0;
      docName = docName || cleanName(body.slice(0, idx));
      content = content || body.slice(idx + markerMatch[0].length).trim();
    }
  }
}

return [{
  json: {
    ...source,
    payload: ctx.payload,
    message: ctx.message,
    chatId: ctx.chatId,
    rawText: raw,
    text: normalized,
    docId,
    docName,
    content,
    hasTarget: Boolean(docId || docName),
    hasContent: Boolean(content),
    response: (docId || docName) && content ? '' : '📝 <b>Append Google Doc</b>\n\nVi du: <code>them vao doc Project Plan: dong moi</code>'
  }
}];

const source = $('Prepare Action').item.json || {};
const rows = $input.all().map((item) => item.json || {}).filter((item) => item.id || item.name);
if (!rows.length) {
  return [{ json: { ...source, docId: '', response: 'Khong tim thay Google Doc phu hop.' } }];
}
const doc = rows[0];
return [{ json: { ...source, docId: doc.id || source.docId || '', docName: doc.name || source.docName || '', webViewLink: doc.webViewLink || '' } }];

const source = $('Prepare Action').item.json || {};
const doc = $input.item.json || {};
const items = Array.isArray(doc.body?.content) ? doc.body.content : [];
const endIndex = items.length ? Number(items[items.length - 1].endIndex || 1) : 1;
return [{ json: { ...source, docId: source.docId, docName: doc.title || source.docName || '', endIndex: endIndex > 1 ? endIndex - 1 : 1 } }];

function escapeHtml(value = '') {
  return String(value)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/\"/g, '&quot;');
}

const source = $('Build Append Request').item.json || $('Prepare Action').item.json || {};
const docId = source.docId || '';
const link = source.webViewLink || (docId ? `https://docs.google.com/document/d/${docId}/edit` : '');
const charCount = String(source.content || '').length;

if (!source.chatId) {
  throw new Error('Missing chatId while formatting Google Docs append response.');
}

let text = '✅ <b>Da them noi dung vao Google Doc</b>\n\n';
text += `<b>${escapeHtml(source.docName || 'Khong ro ten')}</b>\n`;
if (docId) text += `ID: <code>${escapeHtml(docId)}</code>\n`;
text += `So ky tu da them: ${charCount}\n`;
if (link) text += `🔗 <a href="${escapeHtml(link)}">Mo tai lieu</a>`;

return [{ json: { chatId: source.chatId, text: text.trim() } }];
